<?php
declare(strict_types=1);
require __DIR__.'/lib.php';
try { config();auth_start(); } catch(Throwable $e){http_response_code(503);exit('Analytics storage is unavailable.');}
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??''))){http_response_code(403);exit('Reload this page and try again.');}
    if(isset($_POST['logout'])){$_SESSION=[];session_destroy();header('Location: ./');exit;}
    if(!limit('login',10,900)){$error='Too many attempts. Try again in 15 minutes.';http_response_code(429);}
    elseif(password_verify(substr((string)($_POST['password']??''),0,256),config()['password_hash'])){
        session_regenerate_id(true);$_SESSION['authenticated_until']=time()+8*3600;$_SESSION['csrf']=bin2hex(random_bytes(24));header('Location: ./');exit;
    }else{$error='Password not recognised.';http_response_code(401);}
}
