<nav><form method="get"><label for="range">Period</label><select name="range" id="range"><?php foreach(['all'=>'All time','today'=>'Today (UTC)','7'=>'Last 7 days','30'=>'Last 30 days'] as $v=>$label):?><option value="<?=e($v)?>" <?=$range===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><label><input type="checkbox" name="tests" value="1" <?=$tests?'checked':''?>> Debug / QA only</label><button>Refresh</button></form><div class="exports"><a href="export.php?format=json&amp;range=<?=e($range)?>&amp;tests=<?=$tests?1:0?>">JSON export</a><a href="export.php?format=csv&amp;range=<?=e($range)?>&amp;tests=<?=$tests?1:0?>">CSV export</a><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><button name="logout" value="1" class="quiet">Sign out</button></form></div></nav>
<p class="status">Updated <?=e(gmdate('Y-m-d H:i:s'))?> UTC · Tracking since <?=e($r['tracking_since']??'the first incoming visit')?> · <?=$tests?'Debug/QA data — excluded from player totals':'Normal play — debug sessions excluded'?></p>
<div class="cards">
<?php foreach([
 ['Unique players',$r['unique_players'],'Distinct anonymous browsers that pressed Begin'],['Total plays',$plays,'Each Begin / Continue starts a play session'],['Climb attempts',$m['climb_attempts'],'Entering the stairs, including retries after a fall'],['Climbed',$fmt($m['climbed_m']).' m','Upward stair movement; excludes jumps and teleports'],['Walked',$fmt($m['walked_m']).' m','Horizontal distance on the ground or stairs'],['Falls',$m['falls'],'Falls that sent a player to a checkpoint'],['Roof arrivals',$m['roof_arrivals'],'Times players reached the roof'],['Button presses',$m['button_presses'],'Roof action presses; successful activations below'],['Collapses started',$m['collapse_starts'],'The roof switch successfully activated'],['Finished collapses',$m['completions'],'Reached the ending screen'],['Completion rate',$rate.'%','Finished collapses ÷ plays; includes continues'],['Active play',round($m['active_seconds']/60,1).' min','Visible, unpaused gameplay, including the collapse']
] as [$label,$value,$detail]):?><article><p><?=e($label)?></p><strong><?=e(is_numeric($value)?$fmt($value):$value)?></strong><small><?=e($detail)?></small></article><?php endforeach;?>
