<section><h2>More gameplay signals</h2><div class="signals"><?php foreach(['page_views'=>'Page visits','new_games'=>'New games','continues'=>'Continues','jumps'=>'Jumps','auto_jumps'=>'Assisted jumps','short_drops'=>'Nonfatal drops over 1.2 m','crumble_triggers'=>'Crumble warnings','slabs_broken'=>'Slabs broken','figure_grabs'=>'Creature grabs','nerve_stumbles'=>'Nerve stumbles','extinguishes'=>'Successful extinguishes','panic_seconds'=>'Seconds at low nerve'] as $k=>$label):?><div><span><?=e($label)?></span><b><?=$fmt($m[$k])?></b></div><?php endforeach;?><div><span>Average active frame rate</span><b><?=$m['active_seconds']?round($m['frames']/$m['active_seconds'],1):0?> fps</b></div><div><span>Frames slower than 50 ms</span><b><?=$m['frames']?round(100*$m['slow_frames']/$m['frames'],1):0?>%</b></div></div></section>
<section><h2>Recent plays <small>Latest 100 visits in this period</small></h2><div class="tablewrap"><table><thead><tr><th>Started (UTC)</th><th>Platform</th><th>Entry</th><th>Rough location</th><th>Climbed</th><th>Highest</th><th>Falls</th><th>Finished</th></tr></thead><tbody><?php foreach($r['recent'] as $s):?><tr><td><?=e($s['started'])?></td><td><?=e($s['platform'])?></td><td><?=e($s['kind'])?></td><td><?=e(implode(' · ',array_filter([$s['location']['country_name']??'Unknown',$s['location']['region']??null])))?></td><td><?=$fmt($s['meters'])?> m</td><td><?=$fmt($s['height'])?> m</td><td><?=$fmt($s['falls'])?></td><td><?=$s['completed']?'Yes':'—'?></td></tr><?php endforeach;?></tbody></table></div></section>
